package com.greenpulse.service;
import com.greenpulse.domain.*;import com.greenpulse.repository.*;import org.springframework.stereotype.Service;
import java.time.*;import java.math.*;import java.util.*;import java.util.stream.*;import org.springframework.jdbc.core.JdbcTemplate;
@Service
public class AnalyticsService {
 private final ReadingRepository readings;private final BuildingRepository buildings;private final FactorRepository factors;private final CurrentUser current;private final JdbcTemplate jdbc;
 public AnalyticsService(ReadingRepository readings,BuildingRepository buildings,FactorRepository factors,CurrentUser current,JdbcTemplate jdbc){this.readings=readings;this.buildings=buildings;this.factors=factors;this.current=current;this.jdbc=jdbc;}
 public Map<String,Object> dashboard(){var u=current.get();var rows=readings.range(null,current.isSuper(u),current.org(u),LocalDate.now().minusDays(29),LocalDate.now());var total=rows.stream().map(EnergyReading::getEnergyConsumedKwh).reduce(BigDecimal.ZERO,BigDecimal::add);var bs=buildings.scoped(current.isSuper(u),current.org(u));var trend=rows.stream().collect(Collectors.groupingBy(EnergyReading::getReadingDate,TreeMap::new,Collectors.reducing(BigDecimal.ZERO,EnergyReading::getEnergyConsumedKwh,BigDecimal::add))).entrySet().stream().map(e->Map.of("date",e.getKey().toString(),"kwh",e.getValue())).toList();var carbon=emissions(rows);Object[] args=current.isSuper(u)?new Object[]{}:new Object[]{current.org(u)};int alerts=jdbc.queryForObject("SELECT COUNT(*) FROM anomaly_alerts a JOIN buildings b ON b.id=a.building_id WHERE a.status='OPEN'"+(current.isSuper(u)?"":" AND b.organization_id=?"),Integer.class,args);int recommendations=jdbc.queryForObject("SELECT COUNT(*) FROM recommendations r JOIN buildings b ON b.id=r.building_id WHERE r.status='OPEN'"+(current.isSuper(u)?"":" AND b.organization_id=?"),Integer.class,args);return Map.of("totalEnergyKwh",total,"totalEmissionsKg",carbon.getOrDefault("totalKgCo2e",BigDecimal.ZERO),"emissionFactorConfigured",carbon.get("factorConfigured"),"buildingCount",bs.size(),"readingDays",trend.size(),"trend",trend,"activeAlerts",alerts,"recommendationCount",recommendations);}
 public List<Map<String,Object>> trend(LocalDate from,LocalDate to,Long buildingId){var u=current.get();return readings.range(buildingId,current.isSuper(u),current.org(u),from,to).stream().collect(Collectors.groupingBy(EnergyReading::getReadingDate,TreeMap::new,Collectors.reducing(BigDecimal.ZERO,EnergyReading::getEnergyConsumedKwh,BigDecimal::add))).entrySet().stream().map(e->Map.<String,Object>of("date",e.getKey().toString(),"kwh",e.getValue())).toList();}
 public List<Map<String,Object>> comparison(LocalDate from,LocalDate to){var u=current.get();return readings.range(null,current.isSuper(u),current.org(u),from,to).stream().collect(Collectors.groupingBy(r->r.getBuilding().getName(),TreeMap::new,Collectors.reducing(BigDecimal.ZERO,EnergyReading::getEnergyConsumedKwh,BigDecimal::add))).entrySet().stream().map(e->Map.<String,Object>of("building",e.getKey(),"kwh",e.getValue())).toList();}
 public Map<String,Object> emissions(List<EnergyReading> rows){BigDecimal total=BigDecimal.ZERO;var missing=new TreeSet<String>();var details=new ArrayList<Map<String,Object>>();for(var row:rows){String region=row.getBuilding().getOrganization().getCountry();if(region==null||region.isBlank())region="GLOBAL";var factor=factors.effective(region,row.getReadingDate()).stream().findFirst().or(()->factors.effective("GLOBAL",row.getReadingDate()).stream().findFirst());if(factor.isEmpty()){missing.add(region);continue;}BigDecimal kg=row.getEnergyConsumedKwh().multiply(factor.get().getFactor());total=total.add(kg);details.add(Map.of("readingDate",row.getReadingDate().toString(),"building",row.getBuilding().getName(),"energyKwh",row.getEnergyConsumedKwh(),"emissionFactor",factor.get().getFactor(),"factorRegion",factor.get().getRegion(),"factorSource",factor.get().getSource(),"estimatedKgCo2e",kg));}return Map.of("totalKgCo2e",total,"factorConfigured",missing.isEmpty()&&!rows.isEmpty(),"missingFactorRegions",missing,"calculation","Recorded kWh × effective emission factor (kg CO2e/kWh); estimated, not directly measured","readings",details);}
}
